 * @param {string[]} keyColumns - Array of column names to group by.
 * @returns {Promise<Array>} - Array of objects with `key` (combination) and `count` (record count).
 */
async function countByKeyCombinations(df, keyColumns) {
    // Validate input
    if (!df || !Array.isArray(keyColumns) || keyColumns.length === 0) {
        throw new Error("Invalid input: df must be a dataset and keyColumns must be a non-empty array.");
    }

    // Check if all key columns exist in the dataset
    const missingColumns = keyColumns.filter(col => !(col in df));
    if (missingColumns.length > 0) {
        throw new Error(`Missing columns in dataset: ${missingColumns.join(', ')}`);
    }

    // Initialize DuckDB.js (if not already initialized)
    if (!window.duckdb) {
        throw new Error("DuckDB.js not loaded. Include it via CDN or bundle it.");
    }

    // Convert the dataset to a format DuckDB can process (e.g., array of objects)
    const data = Object.keys(df[0]).map(key => df.map(row => row[key]));

    // Create a DuckDB connection and execute the query
    const conn = await window.duckdb.connect();
    try {
        // Register the data as a temporary table
        await conn.register('temp_data', data);

        // Build the GROUP BY clause dynamically
        const groupByClause = keyColumns.map(col => `"${col}"`).join(', ');

        // Execute the query
        const result = await conn.query(`
            SELECT
                ${groupByClause} AS key,
                COUNT(*) AS count
            FROM temp_data
            GROUP BY ${groupByClause}
            ORDER BY key
        `);

        // Convert the result to a JavaScript array of objects
        return result.toArray();
    } finally {
        // Clean up
        await conn.close();
    }
}

