function oneHotEncodeCategorical(df0) {
    // Create a deep copy of the table to avoid mutating the original
    const tableBytes = tableToIPC(df0);
    let table = tableFromIPC(tableBytes);

    // Get schema information
    const schema = table.schema;
    const numRows = table.numRows;

