    const categoricalColumns = [];
    schema.fields.forEach((field, idx) => {
        const type = field.type;
        // Check for string types or dictionary types (common for categorical data)
        if (type.toString().includes('String') || 
            type.toString().includes('Dictionary') ||
            type.toString().includes('Utf8')) {
            categoricalColumns.push({
                name: field.name,
                index: idx,
                type: type
            });
        }
    });

    if (categoricalColumns.length === 0) {
        console.log('No categorical columns found');
        return table;
    }

    // Process each categorical column
    categoricalColumns.forEach(catCol => {
        const colData = table.getColumn(catCol.name);
        const uniqueValues = new Set();

        // Collect unique values
        for (let i = 0; i < numRows; i++) {
            const value = colData.get(i);
            if (value !== null && value !== undefined) {
                uniqueValues.add(value.toString());
            }
        }

        const uniqueValsArray = Array.from(uniqueValues).sort();

