            const safeColumnName = `${catCol.name}_${uniqueVal}`
                .replace(/[^a-zA-Z0-9_]/g, '_')
                .replace(/_{2,}/g, '_');

            newColumnNames.push(safeColumnName);
            newColumns.push(binaryData);
        });

        // Remove the original categorical column
        const columnIndices = Array.from({ length: table.numCols }, (_, i) => i);
        const catColIndex = columnIndices.indexOf(catCol.index);
        columnIndices.splice(catColIndex, 1);

        // Create arrays for remaining columns
        const remainingArrays = [];
        const remainingNames = [];

        columnIndices.forEach(colIdx => {
            const col = table.getColumnAt(colIdx);
            const colDataArray = [];
