            remainingArrays.push(colDataArray);
            remainingNames.push(schema.fields[colIdx].name);
        });

        // Combine remaining columns with new binary columns
        const allArrays = [...remainingArrays, ...newColumns];
        const allNames = [...remainingNames, ...newColumnNames];

        // Create new table
        table = tableFromArrays(allArrays, allNames);
    });

    return table;
