  const headerRow = rows[0];
  const headers = headerRow.querySelectorAll("th");
  const headerMap = new Map(headers.map((th, i) => [th.textContent.trim(), i]));

  // Check if all columns exist
  const missingColumns = columnsToSum.filter(
    (col) => !headerMap.has(col)
  );
  if (missingColumns.length > 0) {
    throw new Error(`Columns not found: ${missingColumns.join(", ")}`);
  }

  // Add result column if it doesn't exist
  const resultHeaderIndex = Array.from(headers).findIndex(
    (th) => th.textContent.trim() === resultColumnName
  );
  if (resultHeaderIndex === -1) {
    const newTh = document.createElement("th");
    newTh.textContent = resultColumnName;
    headerRow.appendChild(newTh);
  }

  // Process rows
  rows.slice(1).forEach((row) => {
    const cells = row.querySelectorAll("td");
    const values = columnsToSum.map((col) => {
      const cellIndex = headerMap.get(col);
      const cellValue = cells[cellIndex]?.textContent.trim();
      return Number(cellValue) || 0;
    });
    const sum = values.reduce((acc, val) => acc + val, 0);

    // Add or update the result cell
    const resultCell = row.querySelector(`td:nth-child(${headerMap.get(resultColumnName) + 1})`);
    if (!resultCell) {
      const newTd = document.createElement("td");
      newTd.textContent = sum;
      row.appendChild(newTd);
    } else {
      resultCell.textContent = sum;
    }
  });
}
