    throw new TypeError('Both input lists must be provided.');
  }

  const n0 = lst0.length;
  const n1 = lst1.length;

  if (typeof n0 !== 'number' || typeof n1 !== 'number') {
    throw new TypeError('Inputs must be array-like with a length property.');
