async function groupAndGather(df0, var0, var1) {
  /**
   * Groups rows by values in var0 column and gathers var1 entries into lists
   * @param {Array<Object>} df0 - Array of objects representing table rows
   * @param {string} var0 - Column name to group by
   * @param {string} var1 - Column name to gather into lists
   * @returns {Promise<Array<Object>>} Array with grouping results
   */

  // Initialize DuckDB
  const db = new duckdb.Database();
  const connection = await db.connect();

