 * Collapse duplicate-named columns by computing means.
 *
 * Input:
 *   { headers: string[], rows: any[][], options?: { parseNumbers?: boolean, skipNaN?: boolean } }
 *
 * Output:
 *   {
 *     collapsedHeaders: string[],           // unique header names (order of first appearance)
 *     collapsedRows: (number|null)[][],     // rows collapsed: each cell is mean across duplicate columns (null if no numeric)
 *     groupOverallMeans: Record<string, number|null> // overall mean across all rows for each header-group
 *   }
 */
function meanByDuplicateHeaders({ headers, rows }, options = {}) {
  const { parseNumbers = true, skipNaN = true } = options;

  if (!Array.isArray(headers)) throw new Error("headers must be an array");
  if (!Array.isArray(rows)) throw new Error("rows must be an array of arrays");

  // Map header -> array of indices
  const groups = new Map();
  headers.forEach((h, i) => {
    const key = String(h);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(i);
  });

  const collapsedHeaders = Array.from(groups.keys());

  // helper to convert a value to number (or NaN)
  const toNumber = (v) => {
    if (v === null || v === undefined || v === "") return NaN;
    if (typeof v === "number") return Number.isFinite(v) ? v : NaN;
    if (typeof v === "string") {
      if (!parseNumbers) return NaN;
      // remove common thousands separators and convert commas for decimals if present
      // Try a few heuristics:
      const trimmed = v.trim();
      // Accept plain numeric strings (including exponential)
      if (/^[+-]?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(trimmed)) return Number(trimmed);
