      // e.g. "1,234.56" -> "1234.56", "1.234,56" likely locale-specific; this is heuristic.
      const noSpaces = trimmed.replace(/\s+/g, "");
      const replaced = noSpaces.replace(/,/g, "");
      const maybe = Number(replaced);
      return Number.isFinite(maybe) ? maybe : NaN;
    }
    return NaN;
  };

  // Compute collapsed rows (per-row means across the duplicate columns)
  const collapsedRows = rows.map((row, rowIdx) => {
    if (!Array.isArray(row)) throw new Error(`row ${rowIdx} is not an array`);
    return collapsedHeaders.map((h) => {
      const indices = groups.get(h);
      let sum = 0;
      let count = 0;
      for (const ci of indices) {
        const raw = row[ci];
        const num = toNumber(raw);
        if (Number.isFinite(num)) {
          sum += num;
          count++;
        } else if (!skipNaN) {
          // treat non-numeric as zero (only if skipNaN===false)
          sum += 0;
          count++;
        }
      }
      if (count === 0) return null; // no numeric value present
      return sum / count;
    });
  });

  // Compute overall mean per group across all rows & duplicate columns
  const groupOverallMeans = {};
  for (const h of collapsedHeaders) {
    const indices = groups.get(h);
    let sum = 0;
    let count = 0;
    for (const row of rows) {
