 * Accepts Arrays, TypedArrays, or any iterable of numeric coordinates.
 *
 * Throws if inputs have different lengths or contain non-finite numbers.
 *
 * Strategies:
 * - For small dimensions, uses Math.hypot(...diffs) for numeric stability/performance.
 * - For larger dimensions, uses compensated summation (Kahan) over squared differences.
 *
 * @param {Iterable<number>} a - first point coordinates
 * @param {Iterable<number>} b - second point coordinates
 * @returns {number} Euclidean distance
 */
function euclideanDistance(a, b) {
