  const A = Array.from(a);
  const B = Array.from(b);

  if (A.length !== B.length) {
    throw new Error('Points must have the same dimensionality (equal length).');
  }

  const n = A.length;
  if (n === 0) return 0;

  // Prepare differences; also validate numbers
  const diffs = new Array(n);
  for (let i = 0; i < n; i++) {
    const ai = +A[i];
    const bi = +B[i];
    if (!Number.isFinite(ai) || !Number.isFinite(bi)) {
      throw new TypeError(`Coordinate at index ${i} is not a finite number.`);
    }
    diffs[i] = ai - bi;
  }

  // For small n, Math.hypot is concise and numerically robust
  if (n <= 512) {
    // Spread is safe for moderate sizes
    return Math.hypot(...diffs);
  }

  // For larger n, avoid argument limits and use Kahan-style compensated summation
  let sum = 0.0;
  let c = 0.0; // compensation
  for (let i = 0; i < n; i++) {
    const y = diffs[i] * diffs[i] - c;
    const t = sum + y;
    c = (t - sum) - y;
    sum = t;
  }
  return Math.sqrt(sum);
}
