/**
 * Compute element-wise sum of two lists of numeric values.
 *
 * @param {Array} a - First list (array-like) of numbers.
 * @param {Array} b - Second list (array-like) of numbers.
 * @param {Object} [opts] - Options:
 *   - mode: 'truncate' | 'pad' | 'strict'  (default: 'truncate')
 *       'truncate' - sum up to min length (default)
 *       'pad'      - treat missing values as 0 and return length = max length
 *       'strict'   - throw if lengths differ
 *   - toNumber: boolean (default true) - coerce elements with Number()
 *   - allowNaN: boolean (default false) - allow NaN values in result
 * @returns {Array<number>} new array with element-wise sums
 * @throws {TypeError} for invalid inputs or when 'strict' mode fails
 */
function elementwiseSum(a, b, opts) {
  opts = Object.assign({ mode: 'truncate', toNumber: true, allowNaN: false }, opts || {});

  if (!Array.isArray(a) || !Array.isArray(b)) {
    throw new TypeError('Both inputs must be arrays.');
  }

  const la = a.length;
  const lb = b.length;

  if (opts.mode === 'strict' && la !== lb) {
    throw new TypeError(`Strict mode: input lengths differ (${la} !== ${lb}).`);
  }

  const length = opts.mode === 'pad' ? Math.max(la, lb) : Math.min(la, lb);
  const out = new Array(length);

  for (let i = 0; i < length; i++) {
    const va = i < la ? a[i] : 0;
    const vb = i < lb ? b[i] : 0;

    const na = opts.toNumber ? Number(va) : va;
    const nb = opts.toNumber ? Number(vb) : vb;

    if (!opts.allowNaN) {
      if (typeof na !== 'number' || Number.isNaN(na)) {
        throw new TypeError(`Non-numeric or NaN value at a[${i}]`);
      }
      if (typeof nb !== 'number' || Number.isNaN(nb)) {
        throw new TypeError(`Non-numeric or NaN value at b[${i}]`);
      }
    }

    out[i] = na + nb;
  }

  return out;
}

