```javascript
/**
 * Fetches all entries from an IndexedDB object store whose keys fall between two boundary keys.
 * @param {string} storeName - The name of the object store
 * @param {string} lowerBound - The lower boundary key (inclusive)
 * @param {string} upperBound - The upper boundary key (inclusive)
 * @param {string} dbName - The IndexedDB database name (default: 'rangeDB')
 * @returns {Promise<Array>} Array of {key, value} objects in the range
 */
async function getRangeEntries(storeName, lowerBound, upperBound, dbName = 'rangeDB') {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(dbName, 1);

    request.onerror = () => reject(new Error('Failed to open database'));

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(storeName)) {
        db.createObjectStore(storeName);
      }
    };

    request.onsuccess = (event) => {
      const db = event.target.result;
      const transaction = db.transaction(storeName, 'readonly');
      const store = transaction.objectStore(storeName);

      // Create a range query: lowerBound <= key <= upperBound
      const range = IDBKeyRange.bound(lowerBound, upperBound, false, false);
      const query = store.getAll(range);

      const results = [];
      query.onsuccess = () => {
        const values = query.result;
        // Get all keys in range
        const keyQuery = store.getAllKeys(range);
        keyQuery.onsuccess = () => {
          const keys = keyQuery.result;
          for (let i = 0; i < keys.length; i++) {
            results.push({ key: keys[i], value: values[i] });
          }
          resolve(results);
        };
      };

      query.onerror = () => reject(new Error('Query failed'));
    };
  });
}

