 * @param {string} csvPath - Path to CSV file or URL
 * @param {string} columnName - Name of the column to search
 * @param {any} targetValue - Value to match
 * @returns {Promise<number>} Count of matching entries
 */
async function countMatchingEntries(csvPath, columnName, targetValue) {
  try {
    // Read the tabular data
