 *   - requireAtLeastOne {boolean} (default false): if true, return NaN for a mean if no valid values; if false return null.
 *
 * @returns {Object} { rowMeans: Array<number|null>, colMeans: Array<number|null> }
 */
function computeSelectedMeans(data, rowIndices = [], colIndices = [], opts = {}) {
  const { ignoreNaN = true, requireAtLeastOne = false } = opts;

  if (!Array.isArray(data) || data.length === 0) {
    throw new Error("data must be a non-empty 2D array");
  }
  const nRows = data.length;
  const nCols = data[0].length;
  for (let r = 0; r < nRows; r++) {
    if (!Array.isArray(data[r]) || data[r].length !== nCols) {
      throw new Error("data must be a rectangular 2D array");
    }
  }

  // Normalize index lists (empty means all)
  const rowIdxList = (Array.isArray(rowIndices) && rowIndices.length > 0)
    ? rowIndices.slice()
    : Array.from({ length: nRows }, (_, i) => i);

  const colIdxList = (Array.isArray(colIndices) && colIndices.length > 0)
    ? colIndices.slice()
    : Array.from({ length: nCols }, (_, i) => i);

  // Helper: validate and filter indices within bounds, preserving order
  function sanitizeIndices(list, limit) {
    return list
      .map(i => Number(i))
      .filter(i => Number.isInteger(i) && i >= 0 && i < limit);
  }

  const rows = sanitizeIndices(rowIdxList, nRows);
  const cols = sanitizeIndices(colIdxList, nCols);

  // Compute row means (each selected row averaged over selected columns)
  const rowMeans = rows.map(r => {
    let sum = 0, count = 0;
    for (const c of cols) {
      const v = data[r][c];
      if (v === undefined || v === null || Number.isNaN(v)) {
        if (ignoreNaN) continue;
        // include NaN (makes result NaN)
        return NaN;
      }
      const num = Number(v);
      if (!Number.isFinite(num)) {
        if (ignoreNaN) continue;
        return NaN;
      }
      sum += num;
      count++;
    }
    if (count === 0) return requireAtLeastOne ? NaN : null;
    return sum / count;
  });

  // Compute column means (each selected column averaged over selected rows)
  const colMeans = cols.map(c => {
    let sum = 0, count = 0;
    for (const r of rows) {
      const v = data[r][c];
      if (v === undefined || v === null || Number.isNaN(v)) {
