```javascript
/**
 * Count occurrences of tuples in a sequence, with optional filtering, ordering, and limiting.
 *
 * sequence: Array of tuples (tuples are arrays; elements can be primitives or plain objects/arrays)
 * options:
 *   - filter(tuple, index) => boolean    // optional predicate to prefilter tuples
 *   - keySelector(tuple) => string       // optional custom key (overrides internal stable stringify)
 *   - orderBy: 'count' | 'key' | function(item)  // default 'count'
 *   - orderDir: 'asc' | 'desc'           // default 'desc'
 *   - limit: number                      // limit output to top N
 *   - returnType: 'array' | 'map'        // default 'array'
 *
 * Returns:
 *   If returnType === 'array': Array of { tuple, count, key }
 *   If returnType === 'map': Map<key, count>
 *
 * Notes:
 * - This stable stringifier handles plain objects/arrays by sorting object keys.
 * - Circular structures are not supported.
 */
function countTuples(sequence, options = {}) {
  const {
    filter = null,
    keySelector = null,
    orderBy = 'count',
    orderDir = 'desc',
    limit = undefined,
    returnType = 'array'
  } = options;

  // Stable stringify: deterministic representation for arrays/objects (sorts object keys)
  function stableStringify(value) {
    const type = typeof value;
    if (value === null) return 'null';
    if (type === 'string') return JSON.stringify(value);
    if (type === 'number' || type === 'boolean') return String(value);
    if (Array.isArray(value)) {
      return '[' + value.map(v => stableStringify(v)).join(',') + ']';
    }
    if (type === 'object') {
      // plain object: sort keys for deterministic order
      const keys = Object.keys(value).sort();
      return '{' + keys.map(k => JSON.stringify(k) + ':' + stableStringify(value[k])).join(',') + '}';
    }
    // fallback for functions/undefined/symbol: encode type
    if (type === 'undefined') return 'undefined';
    return String(value);
  }

  const counts = new Map();

  for (let i = 0; i < sequence.length; i++) {
    const tuple = sequence[i];
    if (typeof filter === 'function' && !filter(tuple, i)) continue;

    const key = (typeof keySelector === 'function') ? keySelector(tuple) : stableStringify(tuple);

    const existing = counts.get(key);
    if (existing) {
      existing.count += 1;
    } else {
      // store the original tuple as-is (note: may be a reference)
      counts.set(key, { key, tuple, count: 1 });
    }
  }

  // Convert to array for ordering/limiting
  let results = Array.from(counts.values());

  // Ordering
  if (orderBy) {
    const getVal = (item) => {
      if (typeof orderBy === 'function') return orderBy(item);
      if (orderBy === 'count') return item.count;
      if (orderBy === 'key') return item.key;
      // fallback: try property access
      return item[orderBy];
    };

    results.sort((a, b) => {
      const va = getVal(a);
      const vb = getVal(b);
      if (va === vb) return 0;
      // handle undefined gracefully
      if (va === undefined) return orderDir === 'asc' ? -1 : 1;
      if (vb === undefined) return orderDir === 'asc' ? 1 : -1;
      if (va < vb) return orderDir === 'asc' ? -1 : 1;
      return orderDir === 'asc' ? 1 : -1;
    });
  }

  // Limit
  if (typeof limit === 'number') {
    results = results.slice(0, limit);
  }

  if (returnType === 'map') {
    const out = new Map();
    for (const r of results) out.set(r.key, r.count);
    return out;
  }

  // default: array of objects
  return results.map(({ tuple, count, key }) => ({ tuple, count, key }));
}
