  const heap = [];
  const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };

  const cmp = (a, b) => {
    if (a.val !== b.val) return a.val - b.val;
    return a.idx - b.idx;
  };

  const siftUp = (i) => {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (cmp(heap[i], heap[parent]) < 0) { swap(i, parent); i = parent; }
      else break;
    }
  };

  const siftDown = (i) => {
    const n = heap.length;
    while (true) {
      let left = 2 * i + 1;
      let right = left + 1;
      let smallest = i;
      if (left < n && cmp(heap[left], heap[smallest]) < 0) smallest = left;
      if (right < n && cmp(heap[right], heap[smallest]) < 0) smallest = right;
      if (smallest === i) break;
      swap(i, smallest);
      i = smallest;
    }
  };

  const pushHeap = (entry) => {
    heap.push(entry);
    siftUp(heap.length - 1);
  };

  const replaceRoot = (entry) => {
    heap[0] = entry;
    siftDown(0);
  };

  // initialize heap with first N elements
  for (let i = 0; i < N; i++) pushHeap({ idx: i, val: arr[i] });

  // process remaining
  for (let i = N; i < len; i++) {
    const candidate = { idx: i, val: arr[i] };
    // if candidate is larger than heap root (which is current N-th largest), replace
    if (cmp(candidate, heap[0]) > 0) {
      replaceRoot(candidate);
    }
  }

  // Extract heap entries and sort descending by value (and by index tie-break)
  const result = heap.slice().sort((a, b) => {
    if (b.val !== a.val) return b.val - a.val;
    return a.idx - b.idx;
  }).map(e => e.idx);

  return result;
}

