 *   [0, 1, 2, 0, 1, 2, 0, 1, 2]
 * );
 * // Returns: [1, 'a', 10, 2, 'b', 20, 3, 'c', 30]
 */
function interleaveBySequence(lists, sequence) {
  // Create iterators for each list
  const iterators = lists.map(list => list[Symbol.iterator]());

  // Track current position in each iterator
  const positions = new Array(lists.length).fill(0);

  // Generate values following the sequence
  const generator = function*() {
    for (const listIndex of sequence) {
      // Validate list index
      if (listIndex < 0 || listIndex >= lists.length) {
        throw new Error(`Invalid sequence index ${listIndex}. Must be between 0 and ${lists.length - 1}`);
