function computeRoots(f, initialEstimate) {
    // Define the function to compute the Jacobian matrix
    function jacobian(f, x, epsilon = 1e-8) {
        const n = x.length;
        const jacobianMatrix = new Array(n).fill(0).map(() => new Array(n).fill(0));
        for (let i = 0; i < n; i++) {
            const xPlusEpsilon = x.slice();
            xPlusEpsilon[i] += epsilon;
            const fPlusEpsilon = f(xPlusEpsilon);
            const xMinusEpsilon = x.slice();
            xMinusEpsilon[i] -= epsilon;
            const fMinusEpsilon = f(xMinusEpsilon);
            for (let j = 0; j < n; j++) {
                jacobianMatrix[i][j] = (fPlusEpsilon[j] - fMinusEpsilon[j]) / (2 * epsilon);
            }
        }
        return jacobianMatrix;
    }

    // Define the function to solve the system of nonlinear equations
    function newtonRaphson(f, initialEstimate, maxIter = 100, tol = 1e-6) {
        let x = initialEstimate;
        for (let i = 0; i < maxIter; i++) {
            const fx = f(x);
            const jacobianMatrix = jacobian(f, x);
            const delta = solveLinearSystem(jacobianMatrix, fx.map(val => -val));
            x = x.map((val, index) => val + delta[index]);
            if (fx.every(val => Math.abs(val) < tol)) {
                break;
            }
        }
        return x;
    }

    // Define the function to solve a linear system of equations
    function solveLinearSystem(matrix, vector) {
        const n = matrix.length;
        const augmentedMatrix = matrix.map((row, index) => [...row, vector[index]]);
        for (let i = 0; i < n; i++) {
            let maxRow = i;
            for (let j = i + 1; j < n; j++) {
                if (Math.abs(augmentedMatrix[j][i]) > Math.abs(augmentedMatrix[maxRow][i])) {
                    maxRow = j;
                }
            }
            [augmentedMatrix[i], augmentedMatrix[maxRow]] = [augmentedMatrix[maxRow], augmentedMatrix[i]];
            for (let j = i + 1; j < n; j++) {
                const factor = augmentedMatrix[j][i] / augmentedMatrix[i][i];
                for (let k = i; k <= n; k++) {
                    augmentedMatrix[j][k] -= factor * augmentedMatrix[i][k];
                }
            }
        }
        const solution = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
            let sum = 0;
            for (let j = i + 1; j < n; j++) {
                sum += augmentedMatrix[i][j] * solution[j];
            }
            solution[i] = (augmentedMatrix[i][n] - sum) / augmentedMatrix[i][i];
        }
        return solution;
    }

    return newtonRaphson(f, initialEstimate);
}

