function solveTwoEq(func, x0, options = {}) {
  const tol = options.tol ?? 1e-10;
  const maxIter = options.maxIter ?? 100;
  const jacEps = options.jacEps ?? 1e-8;
  const lmInit = options.lmInit ?? 1e-6;           // initial Levenberg-Marquardt diag
  const backtrackFactor = options.backtrackFactor ?? 0.5;
  const maxBacktrack = options.maxBacktrack ?? 20;
  const tolDet = options.tolDet ?? 1e-14;

  function norm2(v) { return Math.sqrt(v[0]*v[0] + v[1]*v[1]); }

  // Safe evaluate
  function evalF(x) {
    const f = func([x[0], x[1]]);
    if (!Array.isArray(f) || f.length !== 2 || !isFinite(f[0]) || !isFinite(f[1])) {
      throw new Error("func must return an array [f1,f2] of finite numbers");
    }
    return [f[0], f[1]];
  }

  // Approximate Jacobian with central differences (2x2)
  function approxJacobian(fx, x) {
    const J = [[0, 0], [0, 0]];
    for (let i = 0; i < 2; ++i) {
      const h = jacEps * Math.max(1, Math.abs(x[i]));
      const xp = [x[0], x[1]];
      const xm = [x[0], x[1]];
      xp[i] += h;
      xm[i] -= h;
      const fp = evalF(xp);
      const fm = evalF(xm);
      // column i
      J[0][i] = (fp[0] - fm[0]) / (2 * h);
      J[1][i] = (fp[1] - fm[1]) / (2 * h);
    }
    return J;
  }

