  // Returns {sol: [dx,dy], det}
  function solve2x2(J, r) {
    const a = J[0][0], b = J[0][1], c = J[1][0], d = J[1][1];
    const det = a * d - b * c;
    if (Math.abs(det) <= tolDet) return { sol: null, det };
    const dx = (d * r[0] - b * r[1]) / det;
    const dy = (-c * r[0] + a * r[1]) / det;
    return { sol: [dx, dy], det };
  }

  // Deep clone of x (array)
  let x = [x0[0], x0[1]];

  try {
    let fx = evalF(x);
    let fnorm = norm2(fx);
    if (fnorm < tol) {
      return { root: x, f: fx, iterations: 0, converged: true, message: "Initial guess already within tolerance" };
    }

    let lmLambda = lmInit;

