      }
      if (!solObj.sol) {
        return { root: x, f: fx, iterations: iter-1, converged: false, message: "Jacobian singular and LM failed to regularize" };
      }

      let delta = solObj.sol; // proposed full Newton step

      // Try step with backtracking if necessary
      let alpha = 1.0;
      let accepted = false;
      let newX = null;
      let newF = null;
