 * @param {Object} [options] - Configuration options.
 * @param {boolean} [options.descending=false] - Whether the array is sorted in descending order.
 * @returns {Array} A new array with matching elements removed.
 */
export function removeOrderedElements(arr, predicate, options = {}) {
    const { descending = false } = options;
    const reversed = descending ? (a, b) => b - a : (a, b) => a - b;

    // Step 1: Find all indices to remove using binary search
    const indicesToRemove = [];
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        const midVal = arr[mid];

        if (predicate(midVal)) {
            indicesToRemove.push(mid);
            right = mid - 1; // Search left for more matches
