    // 1) pick one center uniformly at random
    let idx = Math.floor(rnd() * n);
    centers[0] = data[idx];

    // distances squared to nearest chosen center
    const dist2 = new Float64Array(n);
    for (let i = 0; i < n; ++i) {
      const d = data[i] - centers[0];
      dist2[i] = d * d;
    }

    for (let c = 1; c < k; ++c) {
      // compute sum of dist2
      let sum = 0;
      for (let i = 0; i < n; ++i) sum += dist2[i];

      if (sum === 0) {
        // All points coincide with chosen centers; pick random
        centers[c] = data[Math.floor(rnd() * n)];
      } else {
        // pick a data index weighted by dist2
        let r = rnd() * sum;
        let cum = 0;
        let chosen = 0;
        for (let i = 0; i < n; ++i) {
          cum += dist2[i];
          if (r <= cum) { chosen = i; break; }
        }
        centers[c] = data[chosen];
      }

      // update dist2 to nearest center
      for (let i = 0; i < n; ++i) {
        const d = data[i] - centers[c];
        const d2 = d * d;
        if (d2 < dist2[i]) dist2[i] = d2;
      }
    }
