}

// Fallback manual implementation
function manualKMeans(arr0, k, maxIterations, tolerance, initialization) {
    // Convert to 2D points
    const points = arr0.map(value => [value]);
    const n = points.length;

    // Initialize centroids
    let centroids = [];
    if (initialization === 'kmeans++') {
        centroids = kmeansPlusPlusInit(points, k);
    } else {
        // Random initialization
        const shuffled = [...points].sort(() => Math.random() - 0.5);
        centroids = shuffled.slice(0, k).map(p => [...p]);
    }

    let assignments = new Array(n).fill(-1);
    let prevCentroids = null;
    let iteration = 0;

    while (iteration < maxIterations) {
        // Assignment step
        for (let i = 0; i < n; i++) {
            let minDist = Infinity;
            let bestCluster = -1;

            for (let j = 0; j < k; j++) {
                const dist = euclideanDistance(points[i], centroids[j]);
                if (dist < minDist) {
                    minDist = dist;
                    bestCluster = j;
                }
            }
            assignments[i] = bestCluster;
        }

        // Update step
        const newCentroids = Array(k).fill().map(() => [0]);
        const counts = new Array(k).fill(0);

        for (let i = 0; i < n; i++) {
            const cluster = assignments[i];
            newCentroids[cluster][0] += points[i][0];
            counts[cluster]++;
        }

        for (let j = 0; j < k; j++) {
            if (counts[j] > 0) {
                newCentroids[j][0] /= counts[j];
            } else {
                // Reinitialize empty cluster
                const randomIndex = Math.floor(Math.random() * n);
                newCentroids[j] = [...points[randomIndex]];
            }
        }

        // Check convergence
        if (prevCentroids && centroidsConverged(prevCentroids, newCentroids, tolerance)) {
            break;
        }

        prevCentroids = centroids;
        centroids = newCentroids;
        iteration++;
    }

    return assignments;
}

// Helper functions for manual implementation
function euclideanDistance(a, b) {
    return Math.sqrt(a.reduce((sum, val, i) => sum + Math.pow(val - b[i], 2), 0));
}

function centroidsConverged(oldCentroids, newCentroids, tolerance) {
    return oldCentroids.every((centroid, i) => 
        euclideanDistance(centroid, newCentroids[i]) < tolerance
    );
}

function kmeansPlusPlusInit(points, k) {
    const centroids = [];
    const n = points.length;

    // Choose first centroid randomly
    centroids.push([...points[Math.floor(Math.random() * n)]]);

    // Choose remaining centroids
    for (let i = 1; i < k; i++) {
        const distances = points.map(point => {
            const minDist = Math.min(...centroids.map(c => euclideanDistance(point, c)));
            return minDist * minDist; // Square for probability weighting
        });

        const total = distances.reduce((sum, d) => sum + d, 0);
        let threshold = Math.random() * total;
        let cumulative = 0;

        for (let j = 0; j < n; j++) {
            cumulative += distances[j];
            if (cumulative >= threshold) {
                centroids.push([...points[j]]);
                break;
            }
        }
    }

    return centroids;
}

// Dynamic ML5.js loader
async function loadML5() {
    return new Promise((resolve, reject) => {
        if (typeof ml5 !== 'undefined') {
            resolve();
            return;
        }

        const script = document.createElement('script');
        script.src = 'https://unpkg.com/ml5@latest/dist/ml5.min.js';
        script.onload = () => {
            if (typeof ml5 !== 'undefined') {
                resolve();
            } else {
                reject(new Error('Failed to load ML5.js'));
            }
        };
        script.onerror = () => reject(new Error('Failed to load ML5.js'));
        document.head.appendChild(script);
    });
}

