 */
function groupAndCountEvents(df0, groupByColumn, countColumn) {
  try {
    // Validate input columns exist
    if (!df0.columns.includes(groupByColumn)) {
      throw new Error(`Column "${groupByColumn}" not found in DataFrame`);
    }
    if (!df0.columns.includes(countColumn)) {
      throw new Error(`Column "${countColumn}" not found in DataFrame`);
    }

    // Group by the first column and count occurrences in the second
    const grouped = df0.groupby([groupByColumn]).col([countColumn]).count();

    return grouped;
  } catch (error) {
    console.error("Error in groupAndCountEvents:", error.message);
    throw error;
  }
}

/**
 * Alternative implementation using manual grouping for more flexibility
 */
function groupAndCountEventsManual(df0, groupByColumn, countColumn) {
  const groupMap = new Map();

  // Iterate through DataFrame rows
  for (let i = 0; i < df0.shape[0]; i++) {
    const groupValue = df0.loc({ rows: [i] }).values[0][0];
    const countValue = df0.loc({ rows: [i] }).values[0][1];

    if (!groupMap.has(groupValue)) {
      groupMap.set(groupValue, new Map());
    }

    const innerMap = groupMap.get(groupValue);
    innerMap.set(countValue, (innerMap.get(countValue) || 0) + 1);
  }

  // Convert to result array
