```javascript
import * as dfd from "danfo-js-node"; // Danfo.js 2.1.0+ (2024-2025)

/**
 * Adds grouped mean and sum columns to a dataset
 * @param {dfd.DataFrame} df0 - Input dataframe with var0 (grouping) and var1 (values)
 * @returns {dfd.DataFrame} Updated dataframe with var0_mean and var0_sum columns
 */
function addGroupStatistics(df0) {
  // Create a copy to avoid mutating original
  let result = df0.copy();

  // Get unique groups from var0
  const groups = [...new Set(result['var0'].values)];

  // Initialize arrays for mean and sum columns
  const meanColumn = new Array(result.shape[0]);
  const sumColumn = new Array(result.shape[0]);

  // Get values for var1
  const var1Values = result['var1'].values;
  const var0Values = result['var0'].values;

  // Calculate statistics for each group
  groups.forEach(group => {
    const groupIndices = var0Values
      .map((val, idx) => val === group ? idx : -1)
      .filter(idx => idx !== -1);

    const groupValues = groupIndices.map(idx => var1Values[idx]);

    // Calculate mean
    const mean = groupValues.reduce((a, b) => a + b, 0) / groupValues.length;

    // Calculate sum
    const sum = groupValues.reduce((a, b) => a + b, 0);

    // Assign to all rows in this group
    groupIndices.forEach(idx => {
      meanColumn[idx] = mean;
      sumColumn[idx] = sum;
    });
  });

  // Add new columns to dataframe
  result.addColumn({ column: 'var0_mean', values: meanColumn });
  result.addColumn({ column: 'var0_sum', values: sumColumn });

  return result;
}

