/**
 * Sorts a 2D table by columns col0 and col1 in ascending order
 * @param {Array<Array>} df0 - The 2D table to sort
 * @returns {Array<Array>} - The sorted 2D table
 */
function sortTable(df0) {
  const [headers, ...rows] = df0;
  const col0Index = headers.indexOf("col0");
  const col1Index = headers.indexOf("col1");

  rows.sort((a, b) => {
    // Compare col0 first
    if (a[col0Index] !== b[col0Index]) {
      return a[col0Index] > b[col0Index] ? 1 : -1;
    }
    // If col0 is equal, compare col1
    return a[col1Index] > b[col1Index] ? 1 : -1;
  });

  return [headers, ...rows];
}
```

