/**
 * Filters rows from a 2D table where the sum of elements in each row is non-zero
 * @param {number[][] | Array<Array>} df0 - Two-dimensional array (table)
 * @returns {number[][] | Array<Array>} - Filtered table with only non-zero sum rows
 */
function filterNonZeroSumRows(df0) {
  // Import Danfo.js - using 2025+ version
  // In a browser: <script src="https://cdn.jsdelivr.net/npm/danfo-js@latest"></script>
  // In Node.js: npm install danfo-js

  const dfd = require('danfo-js-node'); // or use import in ES modules

  // Convert 2D array to Danfo DataFrame
  const df = new dfd.DataFrame(df0);

  // Calculate row sums using apply
  const rowSums = df.apply((row) => {
    return row.values.reduce((sum, val) => sum + Number(val), 0);
  }, { axis: 1 });

  // Filter rows where sum is not zero
  const filteredDf = df.loc[
    rowSums.map((sum, idx) => sum !== 0 ? idx : null).filter(i => i !== null)
  ];

  // Convert back to 2D array
  return filteredDf.values;
}

