import * as dfd from "danfo-js-node"; // or danfo-js for browser

/**
 * Adds a new column A_perc that contains the percentage of column A
 * relative to the sum of all numeric columns in each row
 * @param {Object} inputTable - Input data as object, array of objects, or Danfo DataFrame
 * @returns {Object} Modified table with new A_perc column
 */
function addPercentageColumn(inputTable) {
  // Convert input to DataFrame if not already
