function splitColumnAtFirstSpace(df0, sourceCol = 'str0', col1 = 'str1', col2 = 'str2') {
  /**
   * Splits a column at the first space character into two new columns
   * @param {dfd.DataFrame} df0 - Input dataframe
   * @param {string} sourceCol - Column to split (default: 'str0')
   * @param {string} col1 - Name of first output column (default: 'str1')
