/**
 * Normalizes each column of a 2D table to scale values between 0 and 1
 * Pure JavaScript implementation
 * 
 * @param {Array<Array<number>>} df0 - A 2D array
 * @returns {Array<Array<number>>} - Normalized 2D array
 */
function normalizeColumns(df0) {
  const numRows = df0.length;
  const numCols = df0[0].length;

  // Create a copy to avoid mutating the original
  const normalized = df0.map(row => [...row]);

  // Process each column
  for (let col = 0; col < numCols; col++) {
    // Find min and max for this column
    let min = normalized[0][col];
    let max = normalized[0][col];

    for (let row = 1; row < numRows; row++) {
      const value = normalized[row][col];
      if (value < min) min = value;
      if (value > max) max = value;
    }

    // Normalize values in this column
    const range = max - min;
    for (let row = 0; row < numRows; row++) {
      normalized[row][col] = range === 0 ? 0 : (normalized[row][col] - min) / range;
    }
  }

  return normalized;
}

