function addSplitColumn(
  df0,
  sourceColumn = "var0",
  targetColumn = "var1",
  delimiter = ",",
  index = 0
) {
  // Extract the source column as an array
  const sourceData = df0[sourceColumn].values;

  // Split each value and extract the specified part
  const splitData = sourceData.map((value) => {
    if (value === null || value === undefined) return null;
    const parts = String(value).split(delimiter);
    return parts[index] ? parts[index].trim() : null;
  });

  // Add the new column to the dataframe
  df0.addColumn({
    column: targetColumn,
    value: splitData,
  });

  return df0;
}

