 * @param {Object|Array} mapping - Either a dict0 (object) for mapping or lst0 (array) for order
 * @returns {Object} - The DataFrame with renamed columns
 */
function renameTableColumns(df0, mapping) {
  // Import Danfo.js (modern data manipulation library for JavaScript)
  const dfd = require('danfo-js-node'); // For Node.js environments
  // OR use: import * as dfd from 'danfo-js'; // For browser environments

  // Check if mapping is a dictionary (object) or list (array)
  if (typeof mapping === 'object' && !Array.isArray(mapping)) {
    // mapping is dict0: { oldName: newName, ... }
    return df0.rename(mapping);
  } 
  else if (Array.isArray(mapping)) {
    // mapping is lst0: array of new column names in order
    const currentColumns = df0.columns;

    if (mapping.length !== currentColumns.length) {
      throw new Error(
        `Column count mismatch: DataFrame has ${currentColumns.length} columns, ` +
        `but ${mapping.length} names provided`
      );
    }

    // Create mapping object from current columns to new names
    const columnMapping = {};
    currentColumns.forEach((col, index) => {
      columnMapping[col] = mapping[index];
    });

    return df0.rename(columnMapping);
  } 
  else {
    throw new Error('Mapping must be either an object (dict) or an array (list)');
  }
}

