/**
 * Calculate conditional column sum using Danfo.js
 * @param {Object|Array} data - DataFrame or array of objects
 * @param {string} columnName - Column to sum
 * @param {string} filterColumn - Column to apply condition on
 * @param {any} filterValue - Value to match
 * @param {string} operator - Comparison operator ('==', '>', '<', '!=', etc.)
 * @returns {number} Conditional sum
 */
function danfoConditionalSum(data, columnName, filterColumn, filterValue, operator = '==') {
  let df;

  // Convert to DataFrame if needed
  if (Array.isArray(data)) {
    df = new dfd.DataFrame(data);
  } else {
    df = data;
  }

  // Apply condition filter
  let filtered;
  switch(operator) {
    case '>': filtered = df.loc[{ columns: [filterColumn] }].gt(filterValue); break;
    case '<': filtered = df.loc[{ columns: [filterColumn] }].lt(filterValue); break;
    case '!=': filtered = df.loc[{ columns: [filterColumn] }].ne(filterValue); break;
    default: filtered = df.loc[{ columns: [filterColumn] }].eq(filterValue);
  }

  // Apply filter and sum
  const result = df[filtered.values].sum();
  return result[columnName];
}

