        start(controller) {
          // Convert input data to Arrow format
          const arrow = require('apache-arrow');
          const table = arrow.tableFromJSON(df0);
          const writer = new arrow.RecordBatchStreamWriter(table.schema);

          table.batches.forEach(batch => {
